jsonTools.init:
function init(eli) {
  if (!eli.events) eli.events = { guard: function (fn) { return fn; }, safeAsync: function (p) { return p; } };
  var bundle = eli.tools._loaded["eli-wrongness"];
  if (!bundle) return;

  _installRealWrongness(eli);
  _installDiagReport(eli);

  function _installRealWrongness(eli) {
    var STORE_WRONGNESS_CAPTURES = "wrongness_captures";
    var STORE_CONFIG = "config";
    var apiVersion = 1;
    var MAX_CAPTURES = 50;
    var DOC_TEXT_FIELDS = /^(docText|document|text|fullText|prompt|aiPrompt|body)$/i;

    // Drain anything the kernel stub buffered before we loaded.
    var stubBuffer = (window.eli.wrongness && typeof window.eli.wrongness._drain === "function")
      ? window.eli.wrongness._drain() : [];
    var _enabled = (window.eli.wrongness && typeof window.eli.wrongness.isEnabled === "function")
      ? window.eli.wrongness.isEnabled() : true;
    // Read persisted toggle.
    eli.storage.get(STORE_CONFIG, "_wrongness_enabled").then(function (row) {
      if (row && row.value === false) _enabled = false;
    }).catch(function () {});

    function isEnabled() { return _enabled; }
    function setEnabled(v) {
      _enabled = !!v;
      eli.storage.put(STORE_CONFIG, { key: "_wrongness_enabled", value: _enabled }).catch(function () {});
      eli.log.event("wrongness", "enabled_changed", { enabled: _enabled });
    }

    function _shortHash(s) {
      var h = 0;
      for (var i = 0; i < s.length; i++) {
        h = ((h << 5) - h) + s.charCodeAt(i);
        h = h | 0;
      }
      return h.toString(36);
    }
    function _sanitizeForCapture(value, key) {
      if (value == null) return value;
      if (typeof value === "string") {
        if (key && DOC_TEXT_FIELDS.test(key) && value.length > 100) {
          return { _eliHashed: true, length: value.length, hash: _shortHash(value) };
        }
        if (value.length > 1000) {
          return { _eliHashed: true, length: value.length, hash: _shortHash(value), preview: value.slice(0, 80) };
        }
        return (window.eli.ai && window.eli.ai.sanitizePII)
          ? window.eli.ai.sanitizePII(value) : value;
      }
      if (typeof value !== "object") return value;
      if (Array.isArray(value)) return value.map(function (v) { return _sanitizeForCapture(v, null); });
      var out = {};
      Object.keys(value).forEach(function (k) { out[k] = _sanitizeForCapture(value[k], k); });
      return out;
    }
    function provenance(extras) {
      return Object.assign({ kernelVersion: window.eli.kernelVersion, timestamp: Date.now() }, extras || {});
    }
    function _trim() {
      return eli.storage.getAll(STORE_WRONGNESS_CAPTURES).then(function (rows) {
        var captures = rows.filter(function (r) { return r.kind === "capture"; });
        if (captures.length <= MAX_CAPTURES) return;
        captures.sort(function (a, b) { return a.capturedAt - b.capturedAt; });
        var toDelete = captures.slice(0, captures.length - MAX_CAPTURES);
        return Promise.all(toDelete.map(function (r) {
          return eli.storage.delete(STORE_WRONGNESS_CAPTURES, r.id);
        }));
      });
    }
    function capture(toolId, input, output, opts) {
      opts = opts || {};
      if (!_enabled) return Promise.resolve(null);
      if (!toolId) return Promise.resolve(null);
      var entry = {
        id: "_capture_" + Date.now() + "_" + Math.floor(Math.random() * 1e6),
        kind: "capture",
        toolId: toolId,
        input: opts.skipSanitize ? input : _sanitizeForCapture(input),
        output: opts.skipSanitize ? output : _sanitizeForCapture(output),
        provenance: opts.provenance || provenance(),
        capturedAt: Date.now(),
      };
      return eli.storage.put(STORE_WRONGNESS_CAPTURES, entry).then(function () {
        eli.log.event("wrongness", "captured", { id: entry.id, toolId: toolId });
        return _trim().then(function () { return entry.id; });
      }).catch(function () { return null; });
    }
    function flag(opts) {
      opts = opts || {};
      if (!opts.findingId) {
        return Promise.reject(new eli.errors.ValidationError("flag requires findingId"));
      }
      var entry = {
        id: "_flag_" + Date.now() + "_" + Math.floor(Math.random() * 1e6),
        kind: "flag",
        findingId: opts.findingId,
        toolId: opts.toolId || null,
        note: String(opts.note || ""),
        provenance: opts.provenance || provenance(),
        flaggedAt: Date.now(),
      };
      return eli.storage.put(STORE_WRONGNESS_CAPTURES, entry).then(function () {
        eli.log.event("wrongness", "flagged", { findingId: opts.findingId, toolId: opts.toolId });
        return entry.id;
      });
    }
    function list(opts) {
      opts = opts || {};
      return eli.storage.getAll(STORE_WRONGNESS_CAPTURES).then(function (rows) {
        if (opts.toolId) rows = rows.filter(function (r) { return r.toolId === opts.toolId; });
        if (opts.kind) rows = rows.filter(function (r) { return r.kind === opts.kind; });
        rows.sort(function (a, b) {
          return (b.capturedAt || b.flaggedAt || 0) - (a.capturedAt || a.flaggedAt || 0);
        });
        if (opts.limit) rows = rows.slice(0, opts.limit);
        return rows;
      });
    }
    function getCapture(id) { return eli.storage.get(STORE_WRONGNESS_CAPTURES, id); }
    function clear() {
      return eli.storage.clearStore(STORE_WRONGNESS_CAPTURES).then(function () {
        eli.log.event("wrongness", "cleared");
      });
    }
    function exportJSON() {
      return list().then(function (entries) {
        return {
          kernelVersion: window.eli.kernelVersion,
          exportedAt: new Date().toISOString(),
          count: entries.length,
          captures: entries.filter(function (e) { return e.kind === "capture"; }),
          flags: entries.filter(function (e) { return e.kind === "flag"; }),
        };
      });
    }
    function copyToClipboard() {
      return exportJSON().then(function (dump) {
        var json = JSON.stringify(dump, null, 2);
        if (typeof window._eliClipboardWriteOrFallback === "function") {
          return window._eliClipboardWriteOrFallback(json, "Wrongness Corpus (" + dump.count + " entries)");
        }
        return navigator.clipboard.writeText(json);
      });
    }
    function replayCapture(id, providersOverride) {
      return getCapture(id).then(function (cap) {
        if (!cap) throw new eli.errors.ValidationError("Capture not found: " + id);
        if (cap.kind !== "capture") throw new eli.errors.ValidationError("Not a capture: " + id);
        var loaded = window.eli.tools._loaded[cap.toolId];
        if (!loaded) throw new eli.errors.ToolError("Tool not loaded: " + cap.toolId);
        var fns = loaded._eliEngineFns || {};
        var engineFn = fns.analyze || fns.run || loaded._eliSimple;
        if (!engineFn) throw new eli.errors.ToolError("Tool has no engine: " + cap.toolId);
        var providers = providersOverride || { host: eli.host, ai: eli.ai, storage: eli.storage };
        var startedAt = Date.now();
        return Promise.resolve(engineFn(cap.input, providers)).then(function (result) {
          return {
            captureId: id, original: cap.output, replay: result,
            ms: Date.now() - startedAt,
            provenance: provenance({ replayOf: id, toolId: cap.toolId }),
          };
        });
      });
    }

    // Install full real impl.
    window.eli.wrongness = {
      apiVersion: apiVersion,
      capture: capture, flag: flag, list: list, getCapture: getCapture,
      clear: clear, exportJSON: exportJSON, copyToClipboard: copyToClipboard,
      replayCapture: replayCapture, provenance: provenance,
      isEnabled: isEnabled, setEnabled: setEnabled, MAX_CAPTURES: MAX_CAPTURES,
    };

    // Replay stub's buffered captures/flags into the real impl.
    stubBuffer.forEach(function (entry) {
      if (entry.kind === "flag" && entry.opts) {
        flag(entry.opts).catch(function () {});
      } else if (entry.toolId) {
        capture(entry.toolId, entry.input, entry.output, entry.opts || {}).catch(function () {});
      }
    });
    eli.log.event("wrongness", "real_provider_installed", { replayedOps: stubBuffer.length });
  }

  function _installDiagReport(eli) {
    window.eli.diag.report = function () {
      var report = {
        kernelVersion: window.eli.kernelVersion,
        schemaVersion: window.eli.schemaVersion,
        timestamp: new Date().toISOString(),
        selfTest: window.eli.diag.selfTest(),
        perf: window.eli.perf.list(),
        fsm: window.eli.fsm ? window.eli.fsm.current() : null,
        apiVersions: {
          host: window.eli.host && window.eli.host.apiVersion,
          ai: window.eli.ai && window.eli.ai.apiVersion,
          storage: window.eli.storage && window.eli.storage.apiVersion,
          tools: window.eli.tools && window.eli.tools.apiVersion,
          wrongness: window.eli.wrongness && window.eli.wrongness.apiVersion,
        },
        state: {
          apiKeySet: window.eli.ai ? window.eli.ai.hasApiKey() : false,
          online: typeof navigator !== "undefined" ? navigator.onLine : null,
          hostCapabilities: window.eli.host ? window.eli.host.capabilities() : null,
          activityCount: window.eli.activity && window.eli.activity.list ? window.eli.activity.list().length : 0,
          logCount: window.eli.log ? window.eli.log.list().length : 0,
          cancelTokensActive: window.eli.cancel ? window.eli.cancel.activeCount() : 0,
          registeredChannels: window.eli.list(),
          user: window.eli.tools && window.eli.tools.userIdentity
            ? window.eli.tools.userIdentity() : null,
        },
        recentLog: window.eli.log ? window.eli.log.list({ limit: 50 }) : [],
        loadedTools: window.eli.tools && window.eli.tools._loaded
          ? Object.keys(window.eli.tools._loaded) : [],
        debugMode: typeof ELI_DEBUG !== "undefined" ? ELI_DEBUG : false,
      };
      return Promise.resolve(window.eli.storage.estimate())
        .then(function (e) { report.state.storage = e; return report; })
        .catch(function () { return report; });
    };
    window.eli.diag.copyToClipboard = function () {
      return window.eli.diag.report().then(function (r) {
        var json = JSON.stringify(r, null, 2);
        if (typeof window._eliClipboardWriteOrFallback === "function") {
          return window._eliClipboardWriteOrFallback(json, "ELI Diagnostic Report");
        }
        return navigator.clipboard.writeText(json);
      });
    };
  }

  eli.log.event("tool", "eli_wrongness_initialized", {});
}
